// ========================================================
// Medicine Normalization
// n8n Code Node
// Mode: Run Once for All Items
// ========================================================

// --------------------------------------------------------
// 0. توحيد أسماء الأعمدة لكل مورد (بدل نودز Edit Fields)
//    المورد يُعرف تلقائياً من أعمدة الشيت
// --------------------------------------------------------

const SUPPLIERS = [
  {
    supplier: 'AlShifa',
    columns: {
      code: 'Item Code', name: 'Product Name', dose: 'Strength',
      form: 'Dosage Form', package: 'Pack', quantity: 'Qty',
      price: 'Price', brand: 'Manufacturer', barcode: 'Barcode'
    }
  },
  {
    supplier: 'MedLine',
    columns: {
      code: 'SKU', name: 'Medicine', dose: 'Dose',
      form: 'Form Type', package: 'Package', quantity: 'Stock',
      price: 'Unit Price', brand: 'MFR', barcode: 'GTIN'
    }
  },
  {
    supplier: 'CarePlus',
    columns: {
      code: 'Code', name: 'Trade Name', dose: 'Concentration',
      form: 'Form', package: 'Pack Size', quantity: 'Available',
      price: 'Cost', brand: 'Company', barcode: 'Barcode No'
    }
  },
  {
    supplier: 'PharmaSource',
    columns: {
      code: 'Product_ID', name: 'Description', dose: 'Power',
      form: 'Dosage', package: 'Box', quantity: 'On Hand',
      price: 'Net Cost', brand: 'Brand Owner', barcode: 'EAN'
    }
  }
];

const headerKey = h => String(h).trim().toLowerCase().replace(/[\s_]+/g, ' ');

const UNIFIED = ['code', 'name', 'dose', 'form', 'package', 'quantity', 'price', 'brand', 'barcode', 'supplier'];

function mapRow(raw) {

  // الصف موحد مسبقاً (جاي من نود Edit Fields) => نمرره كما هو
  const unifiedHits = UNIFIED.filter(f => f in raw).length;
  if (unifiedHits >= 8) {
    const out = {};
    for (const f of UNIFIED) out[f] = f in raw ? raw[f] : '';
    return out;
  }

  // فهرس الأعمدة بعد تنظيف الأسماء (مسافات / حالة الأحرف)
  const index = {};
  for (const k of Object.keys(raw)) index[headerKey(k)] = k;

  // المورد = اللي كل أعمدته موجودة، والأكثر تطابقاً
  let best = null;
  let bestHits = 0;
  for (const s of SUPPLIERS) {
    const hits = Object.values(s.columns).filter(c => headerKey(c) in index).length;
    if (hits > bestHits) { best = s; bestHits = hits; }
  }

  if (!best || bestHits < 7) {
    return {
      code: '', name: '', dose: '', form: '', package: '',
      quantity: 0, price: null, brand: '', barcode: '',
      supplier: 'Unknown',
      _mapError: `أعمدة غير معروفة: ${Object.keys(raw).join(', ')}`
    };
  }

  const out = { supplier: best.supplier };
  for (const [field, col] of Object.entries(best.columns)) {
    const key = index[headerKey(col)];
    out[field] = key === undefined ? '' : raw[key];
  }
  return out;
}

const inputItems = $input.all()
  .filter(item => item.json && Object.keys(item.json).length)
  .map(item => ({ json: mapRow(item.json) }));


// --------------------------------------------------------
// 1. Basic helpers
// --------------------------------------------------------

function rawString(value) {
  if (value === null || value === undefined) return '';

  return String(value)
    .normalize('NFKC')
    .trim();
}


function cleanText(value) {
  return rawString(value)
    .toLowerCase()
    .replace(/[–—−]/g, '-')
    .replace(/[_.]+/g, ' ')
    .replace(/[-]+/g, ' ')
    .replace(/[()\[\]{},;:]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}


function formatNumber(n) {
  if (!Number.isFinite(n)) return '';

  const rounded =
    Math.round((n + Number.EPSILON) * 1000000) / 1000000;

  return Number.isInteger(rounded)
    ? String(rounded)
    : String(rounded)
        .replace(/0+$/, '')
        .replace(/\.$/, '');
}


// --------------------------------------------------------
// 2. Dose normalization
// --------------------------------------------------------

function toMg(value, unit) {

  const n = Number(
    String(value).replace(',', '.')
  );

  if (!Number.isFinite(n)) {
    return null;
  }

  const u = unit.toLowerCase();

  // gram -> mg
  if (u === 'g' || u === 'gm') {
    return n * 1000;
  }

  // microgram -> mg
  if (
    u === 'mcg' ||
    u === 'ug' ||
    u === 'µg' ||
    u === 'μg'
  ) {
    return n / 1000;
  }

  // already mg
  if (u === 'mg') {
    return n;
  }

  return null;
}


function normalizeDose(value) {

  let s = rawString(value)
    .toLowerCase()
    .replace(/,/g, '.')
    .replace(/micrograms?/g, 'mcg')
    .replace(/mcgs?/g, 'mcg')
    .replace(/[µμ]g/g, 'mcg')
    .replace(/milligrams?/g, 'mg')
    .replace(/mgs?/g, 'mg')
    .replace(/grams?/g, 'g')
    .replace(/gms?/g, 'gm')
    .replace(/\s+/g, ' ')
    .trim();


  if (!s) {
    return '';
  }


  // --------------------------------
  // Combination strength
  //
  // Example:
  // 875 mg / 125 mg
  // --------------------------------

  const combo = s.match(
    /(\d+(?:\.\d+)?)\s*(mcg|ug|mg|gm|g)?\s*[\/+]\s*(\d+(?:\.\d+)?)\s*(mcg|ug|mg|gm|g)\b/
  );


  if (combo) {

    const unit2 = combo[4];
    const unit1 = combo[2] || unit2;

    const a = toMg(combo[1], unit1);
    const b = toMg(combo[3], unit2);

    if (a !== null && b !== null) {

      return (
        `${formatNumber(a)} mg / ` +
        `${formatNumber(b)} mg`
      );
    }
  }


  // --------------------------------
  // Normal single strength
  // --------------------------------

  const match = s.match(
    /(\d+(?:\.\d+)?)\s*(mcg|ug|mg|gm|g)\b/
  );


  if (!match) {
    return cleanText(s);
  }


  const mg = toMg(
    match[1],
    match[2]
  );


  if (mg === null) {
    return cleanText(s);
  }


  return `${formatNumber(mg)} mg`;
}


// --------------------------------------------------------
// 3. Numbers belonging to dose
//
// Needed because suppliers sometimes put dose
// inside medicine name.
//
// Example:
//
// Brufen 400
// Losec 20
// Augmentin 1000
//
// --------------------------------------------------------

function doseNumbers(originalDose, normalizedDose) {

  const result = new Set();

  const original =
    rawString(originalDose)
      .replace(/,/g, '.');

  const normalized =
    rawString(normalizedDose)
      .replace(/,/g, '.');


  for (
    const match of
    original.matchAll(/\d+(?:\.\d+)?/g)
  ) {

    result.add(
      formatNumber(Number(match[0]))
    );
  }


  for (
    const match of
    normalized.matchAll(/\d+(?:\.\d+)?/g)
  ) {

    result.add(
      formatNumber(Number(match[0]))
    );
  }


  return result;
}


// --------------------------------------------------------
// 4. Medicine name normalization
// --------------------------------------------------------

function normalizeName(
  value,
  originalDose,
  normalizedDose
) {

  let s = cleanText(value);

  if (!s) {
    return '';
  }


  // --------------------------------
  // Remove explicit doses
  //
  // Augmentin 1g
  // Amoxil 500mg
  // --------------------------------

  s = s
    .replace(
      /\b\d+(?:\.\d+)?\s*(?:mcg|ug|µg|μg|mg|gm|g)\b/g,
      ' '
    )
    .replace(/\s+/g, ' ')
    .trim();


  // --------------------------------
  // Remove standalone number
  // ONLY if it belongs to dose.
  //
  // Brufen 400 + 400mg
  // => Brufen
  //
  // This is safer than removing
  // every number from every name.
  // --------------------------------

  const numbers = doseNumbers(
    originalDose,
    normalizedDose
  );


  s = s
    .split(' ')
    .filter(token => {

      if (
        !/^\d+(?:\.\d+)?$/.test(token)
      ) {
        return true;
      }

      return !numbers.has(
        formatNumber(Number(token))
      );
    })
    .join(' ');


  // --------------------------------
  // Remove dosage form words when
  // suppliers append them to name.
  //
  // Amoxil Caps
  // Zyrtec Tabs
  // Ventolin Evohaler
  // --------------------------------

  const removable = new Set([
    'tab',
    'tabs',
    'tablet',
    'tablets',

    'cap',
    'caps',
    'capsule',
    'capsules',

    'inhaler',
    'inhalers',
    'evohaler'
  ]);


  s = s
    .split(' ')
    .filter(
      token => !removable.has(token)
    )
    .join(' ')
    .replace(/\s+/g, ' ')
    .trim();


  return s;
}


// --------------------------------------------------------
// 5. Dosage form normalization
// --------------------------------------------------------

function normalizeForm(value) {

  const s = cleanText(value);

  if (!s) {
    return '';
  }


  // IMPORTANT:
  // Specific forms before generic forms.

  if (
    /efferv/.test(s) &&
    /\b(tab|tabs|tablet|tablets)\b/.test(s)
  ) {
    return 'effervescent tablet';
  }


  if (
    /inhal|evohaler|metered dose/.test(s)
  ) {
    return 'inhaler';
  }


  if (
    /\b(tab|tabs|tablet|tablets)\b/.test(s)
  ) {
    return 'tablet';
  }


  if (
    /\b(cap|caps|capsule|capsules)\b/.test(s)
  ) {
    return 'capsule';
  }


  if (
    /\b(syrup|syr)\b/.test(s)
  ) {
    return 'syrup';
  }


  if (
    /suspension|\bsusp\b/.test(s)
  ) {
    return 'suspension';
  }


  if (/cream/.test(s)) {
    return 'cream';
  }


  if (
    /ointment|\boint\b/.test(s)
  ) {
    return 'ointment';
  }


  if (
    /injection|injectable|\binj\b/.test(s)
  ) {
    return 'injection';
  }


  if (/drops?/.test(s)) {
    return 'drops';
  }


  return s;
}


// --------------------------------------------------------
// 6. Package normalization
// --------------------------------------------------------

function normalizePackage(value) {

  const s = cleanText(value)

    .replace(/box of/g, ' ')

    .replace(/boxes?\b/g, ' ')

    .replace(/packs?\b/g, ' ')

    .replace(/['’]s\b/g, ' ')

    .replace(/\s+/g, ' ')

    .trim();


  if (!s) {
    return '';
  }


  // --------------------------------
  // Example:
  // 2 x 14
  // => 28
  // --------------------------------

  const multiplication =
    s.match(
      /\b(\d+)\s*[x×]\s*(\d+)\b/
    );


  if (multiplication) {

    return String(
      Number(multiplication[1]) *
      Number(multiplication[2])
    );
  }


  // --------------------------------
  // Examples:
  //
  // 24 Tabs
  // BOX 24
  // 20'S
  // 200 PUFFS
  //
  // => only package count
  // --------------------------------

  const firstNumber =
    s.match(/\b\d+\b/);


  if (firstNumber) {

    return String(
      Number(firstNumber[0])
    );
  }


  return s;
}


// --------------------------------------------------------
// 7. Manufacturer normalization
// --------------------------------------------------------

function normalizeBrand(value) {

  const s = cleanText(value);

  if (!s) {
    return '';
  }


  // Ignore:
  // case
  // spaces
  // punctuation

  return s.replace(
    /[^a-z0-9]/g,
    ''
  );
}


// --------------------------------------------------------
// Display manufacturer nicely
// --------------------------------------------------------

function displayBrand(
  brandKey,
  originalBrand
) {

  const known = {

    haleon: 'Haleon',

    gsk: 'GSK',

    abbott: 'Abbott',

    astrazeneca: 'AstraZeneca',

    merck: 'Merck',

    pfizer: 'Pfizer',

    msd: 'MSD',

    ucb: 'UCB',

    demopharma: 'Demo Pharma',

    newcare: 'NewCare'
  };


  return (
    known[brandKey] ||
    rawString(originalBrand)
      .replace(/\s+/g, ' ')
      .trim()
  );
}


// --------------------------------------------------------
// 8. Barcode normalization
// --------------------------------------------------------

function normalizeBarcode(value) {

  if (value === null || value === undefined) return '';

  // رقم حقيقي (Google Sheets UNFORMATTED_VALUE)
  if (typeof value === 'number') {
    if (!Number.isSafeInteger(value) || value <= 0) return '';
    const digits = String(value);
    return digits.length >= 8 && digits.length <= 14 ? digits : '';
  }

  let s = rawString(value);
  if (!s) return '';

  // صيغة علمية مثل 6.29E+12 => الأرقام ضاعت، لا نثق بها
  if (/e[+-]?\d+/i.test(s)) return '';

  // 6291001000011.0 => 6291001000011
  s = s.replace(/\.0+$/, '');

  const digits = s.replace(/\D/g, '');

  // باركود صالح: 8 إلى 14 رقم (EAN-8 / UPC / EAN-13 / GTIN-14)
  return digits.length >= 8 && digits.length <= 14 ? digits : '';
}


// --------------------------------------------------------
// Display medicine name
// --------------------------------------------------------

function titleCase(value) {

  return rawString(value)
    .toLowerCase()
    .replace(
      /\b\w/g,
      c => c.toUpperCase()
    );
}


// --------------------------------------------------------
// Compare core medicine fields
// --------------------------------------------------------

function sameCore(
  a,
  b,
  ignoreDose = false
) {

  if (
    !a.normalizedName ||
    !b.normalizedName ||
    a.normalizedName !==
    b.normalizedName
  ) {
    return false;
  }


  if (
    a.normalizedForm &&
    b.normalizedForm &&
    a.normalizedForm !==
    b.normalizedForm
  ) {
    return false;
  }


  if (
    a.normalizedPackage &&
    b.normalizedPackage &&
    a.normalizedPackage !==
    b.normalizedPackage
  ) {
    return false;
  }


  if (
    a.normalizedBrandKey &&
    b.normalizedBrandKey &&
    a.normalizedBrandKey !==
    b.normalizedBrandKey
  ) {
    return false;
  }


  if (
    !ignoreDose &&
    a.normalizedDose &&
    b.normalizedDose &&
    a.normalizedDose !==
    b.normalizedDose
  ) {
    return false;
  }


  return true;
}


// --------------------------------------------------------
// Numbers (price / quantity)
// --------------------------------------------------------

function parseNumber(value) {
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  const s = rawString(value).replace(/[^\d.,-]/g, '').replace(',', '.');
  if (!s) return null;
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}


function titleForm(value) {
  return rawString(value).replace(/\b\w/g, c => c.toUpperCase());
}


// 0.1 mg => 100 mcg (للعرض فقط، المطابقة تبقى بالـ mg)
function displayDose(dose) {
  return rawString(dose).replace(/(\d+(?:\.\d+)?) mg/g, (m, n) => {
    const v = Number(n);
    return v > 0 && v < 1 ? `${formatNumber(v * 1000)} mcg` : m;
  });
}


function mostCommon(values) {
  const counts = new Map();
  for (const v of values) {
    if (!v) continue;
    counts.set(v, (counts.get(v) || 0) + 1);
  }
  let best = '';
  let bestCount = 0;
  for (const [v, c] of counts) {
    if (c > bestCount) { best = v; bestCount = c; }
  }
  return best;
}


// ========================================================
// 9. Normalize every input item (unified schema)
// ========================================================

const UNIFIED_FIELDS = [
  'code', 'name', 'dose', 'form', 'package',
  'quantity', 'price', 'brand', 'barcode', 'supplier'
];

const rows = inputItems.map((item, index) => {

  const j = item.json || {};

  // تأكد أن كل الحقول الموحدة موجودة
  const missing = UNIFIED_FIELDS.filter(f => !(f in j));

  const normalizedDose = normalizeDose(j.dose);
  const normalizedName = normalizeName(j.name, j.dose, normalizedDose);
  const normalizedBrandKey = normalizeBrand(j.brand);

  const price = parseNumber(j.price);
  const quantityRaw = parseNumber(j.quantity);
  const quantity = quantityRaw === null ? 0 : Math.max(0, quantityRaw);

  const notes = [];
  if (missing.length) notes.push(`حقول ناقصة: ${missing.join(', ')}`);
  if (j._mapError) notes.push(j._mapError);
  if (price === null || price <= 0) notes.push('سعر غير صالح');
  if (rawString(j.barcode) && !normalizeBarcode(j.barcode)) notes.push('باركود غير صالح');

  return {
    supplier: rawString(j.supplier),
    supplierCode: rawString(j.code),
    originalName: rawString(j.name),
    price,
    quantity,

    normalizedName,
    normalizedDose,
    normalizedForm: normalizeForm(j.form),
    normalizedPackage: normalizePackage(j.package),
    normalizedBrandKey,
    normalizedBrand: displayBrand(normalizedBrandKey, j.brand),
    normalizedBarcode: normalizeBarcode(j.barcode),

    doseInferred: false,
    matchMethod: '',
    matchConfidence: '',
    matchKey: '',
    notes,
    _inputIndex: index
  };
});


// ========================================================
// 10. Matching priority #1 : Barcode / GTIN / EAN
// ========================================================

for (const row of rows) {
  if (row.normalizedBarcode) {
    row.matchKey = `gtin:${row.normalizedBarcode}`;
    row.matchMethod = 'barcode';
    row.matchConfidence = 'very-high';
  }
}


// ========================================================
// 11. Matching priority #2 : infer barcode from fields
// ========================================================

const knownBarcodeRows = rows.filter(row => row.normalizedBarcode);

for (const row of rows) {

  if (row.matchKey) continue;

  const ignoreDose = !row.normalizedDose;

  const candidates = knownBarcodeRows.filter(
    candidate => sameCore(row, candidate, ignoreDose)
  );

  const uniqueBarcodes = [
    ...new Set(candidates.map(c => c.normalizedBarcode).filter(Boolean))
  ];

  if (uniqueBarcodes.length === 1) {

    row.matchKey = `gtin:${uniqueBarcodes[0]}`;
    row.matchMethod = ignoreDose ? 'unique-core-inference' : 'normalized-fields-to-barcode';
    row.matchConfidence = ignoreDose ? 'medium' : 'high';

    if (!row.normalizedDose) {
      const doses = [...new Set(candidates.map(c => c.normalizedDose).filter(Boolean))];
      if (doses.length === 1) {
        row.normalizedDose = doses[0];
        row.doseInferred = true;
        row.notes.push('الجرعة مستنتجة من الباركود');
      }
    }
  }
}


// ========================================================
// 12. Fallback : composite key
// ========================================================

for (const row of rows) {
  if (!row.matchKey) {
    row.matchKey = 'cmp:' + [
      row.normalizedName,
      row.normalizedDose,
      row.normalizedForm,
      row.normalizedPackage,
      row.normalizedBrandKey
    ].join('|');
    row.matchMethod = 'composite-key';
    row.matchConfidence = 'normal';
  }
}


// ========================================================
// 13. Canonical values per product
//
// كل الصفوف التي تخص نفس المنتج تأخذ نفس القيم الموحدة
// (الأكثر تكراراً) حتى يطلع عمود medicine متطابق حرفياً.
// ========================================================

const groups = new Map();
for (const row of rows) {
  if (!groups.has(row.matchKey)) groups.set(row.matchKey, []);
  groups.get(row.matchKey).push(row);
}

for (const members of groups.values()) {

  const canonical = {
    name: mostCommon(members.map(r => r.normalizedName)),
    dose: mostCommon(members.map(r => r.normalizedDose)),
    doseDisplay: '',
    form: mostCommon(members.map(r => r.normalizedForm)),
    pack: mostCommon(members.map(r => r.normalizedPackage)),
    brand: mostCommon(members.map(r => r.normalizedBrand)),
    barcode: mostCommon(members.map(r => r.normalizedBarcode)),
  };

  // عمود واحد يجمع كل معلومات الدواء — هو أساس المقارنة
  const medicine = [
    titleCase(canonical.name),
    displayDose(canonical.dose),
    titleForm(canonical.form),
    canonical.pack ? `${canonical.pack} units` : '',
    canonical.brand
  ].filter(Boolean).join(' | ');

  canonical.doseDisplay = displayDose(canonical.dose);

  for (const row of members) {
    row.medicine = medicine;
    row.canonical = canonical;
  }
}


// ========================================================
// 14. Return to n8n
// ========================================================

return rows.map(({ _inputIndex, notes, ...json }) => ({
  json: { ...json, notes: notes.join(' ; ') }
}));

// ========================================================
// Best price per medicine
// Mode: Run Once for All Items
//
// المقارنة على عمود واحد: medicine
// ========================================================

const rows = $input.all().map(i => i.json);

const round2 = n => Math.round((n + Number.EPSILON) * 100) / 100;


// --------------------------------------------------------
// 1. تجميع حسب عمود medicine
// --------------------------------------------------------

const groups = new Map();
for (const r of rows) {
  if (!r.medicine) continue;
  if (!groups.has(r.medicine)) groups.set(r.medicine, []);
  groups.get(r.medicine).push(r);
}


const output = [];

for (const [medicine, members] of groups) {

  const notes = new Set();

  // --------------------------------------------------------
  // 2. إزالة التكرار داخل نفس المورد
  //    (نفس الدواء مكرر عند مورد واحد => نأخذ أرخص عرض صالح)
  // --------------------------------------------------------

  const bySupplier = new Map();
  for (const r of members) {
    if (r.notes) r.notes.split(' ; ').forEach(n => n && notes.add(`${r.supplier}: ${n}`));
    if (r.price === null || r.price <= 0) continue;

    const prev = bySupplier.get(r.supplier);
    if (prev) {
      notes.add(
        prev.supplierCode === r.supplierCode
          ? `${r.supplier}: صف مكرر (${r.supplierCode})`
          : `${r.supplier}: عرضان لنفس الدواء (${prev.supplierCode}, ${r.supplierCode})`
      );
      const better =
        (r.quantity > 0 && prev.quantity === 0) ||
        ((r.quantity > 0) === (prev.quantity > 0) && r.price < prev.price);
      if (!better) continue;
    }
    bySupplier.set(r.supplier, r);
  }

  const offers = [...bySupplier.values()].sort((a, b) => a.price - b.price);
  const inStock = offers.filter(o => o.quantity > 0);


  // --------------------------------------------------------
  // 3. أفضل سعر = أقل سعر عند مورد عنده مخزون
  // --------------------------------------------------------

  let best = null;
  let bestSuppliers = [];

  if (inStock.length) {
    const minPrice = inStock[0].price;
    const tied = inStock.filter(o => o.price === minPrice);
    // عند التعادل: الأكثر مخزوناً أولاً
    tied.sort((a, b) => b.quantity - a.quantity);
    best = tied[0];
    bestSuppliers = tied.map(o => o.supplier);
  }

  const cheapestListed = offers[0];
  if (cheapestListed && best && cheapestListed.price < best.price) {
    notes.add(`أرخص سعر عند ${cheapestListed.supplier} (${cheapestListed.price}) لكن المخزون صفر`);
  }

  const highest = inStock.length ? inStock[inStock.length - 1].price : null;
  const c = members[0].canonical || {};

  output.push({
    json: {
      medicine,
      barcode: c.barcode || '',
      name: members[0].medicine.split(' | ')[0],
      dose: c.doseDisplay || c.dose || '',
      form: c.form || '',
      pack_size: c.pack || '',
      manufacturer: c.brand || '',

      status: best ? 'متوفر' : 'غير متوفر لدى أي مورد',
      best_price: best ? best.price : '',
      best_supplier: bestSuppliers.join(', '),
      best_supplier_sku: best ? best.supplierCode : '',
      best_supplier_stock: best ? best.quantity : 0,

      highest_price_in_stock: highest ?? '',
      saving_vs_highest: best && highest !== null ? round2(highest - best.price) : '',
      suppliers_in_stock: inStock.length,
      total_stock: inStock.reduce((s, o) => s + o.quantity, 0),

      all_offers: offers
        .map(o => `${o.supplier}: ${o.price}${o.quantity > 0 ? ` (${o.quantity})` : ' (نفد)'}`)
        .join(' | '),

      match_method: [...new Set(members.map(m => m.matchMethod))].join(', '),
      notes: [...notes].join(' ; ')
    }
  });
}

output.sort((a, b) => a.json.medicine.localeCompare(b.json.medicine));

return output;
